    std::vector<std::uint8_t> island_damage_source()
    {
        std::vector<std::uint8_t> bytes;
        bytes.reserve(island_damage_source_hex.size()/2);
        const auto digit = [](const char c) -> std::uint8_t
        {
            if (c >= '0' && c <= '9') return static_cast<std::uint8_t>(c - '0');
            if (c >= 'a' && c <= 'f') return static_cast<std::uint8_t>(c - 'a' + 10);
            throw std::runtime_error("corrupt pinned Island damage fixture hex");
        };
        for (std::size_t i = 0; i < island_damage_source_hex.size(); i += 2)
            bytes.push_back(static_cast<std::uint8_t>(16 * digit(island_damage_source_hex[i]) + digit(island_damage_source_hex[i+1])));
        return bytes;
    }

